/**
 * Crea el tema canónico tema-130: "Prevención de riesgos laborales: marco
 * y desarrollo normativo, medidas mínimas de seguridad en la
 * construcción, salud e higiene con especial atención a los agentes
 * biológicos" y lo asigna como Tema 12 (bloque-2, numero=14) de la
 * oposición Oficial Cementerio (Ayto. Zaragoza).
 *
 * Corresponde al TEMA 12 oficial del Anexo I (bases2110.pdf):
 * "Prevención de riesgos laborales: Marco y desarrollo normativo. Medidas
 * mínimas de seguridad en la construcción. Salud e higiene, especial
 * atención a los agentes biológicos."
 *
 * Fuentes primarias verificadas:
 * - Ley 31/1995, de Prevención de Riesgos Laborales (marco general, ya
 *   verificada en sesiones anteriores del proyecto).
 * - RD 1627/1997, disposiciones mínimas de seguridad y salud en obras de
 *   construcción (ya citado en el tema-127 de esta misma oposición).
 * - RD 664/1997, de 12 de mayo, sobre la protección de los trabajadores
 *   contra los riesgos relacionados con la exposición a agentes
 *   biológicos durante el trabajo (BOE-A-1997-11144), verificado
 *   mediante búsqueda en esta misma sesión de trabajo — especialmente
 *   relevante para el trabajo de cementerio por el riesgo biológico
 *   asociado a exhumaciones y manipulación de restos.
 *
 * Tres secciones:
 * 1. marco-desarrollo-normativo-prl
 * 2. medidas-minimas-seguridad-construccion
 * 3. salud-higiene-agentes-biologicos
 *
 * Uso: node --env-file=.env.local scripts/seed-tema-130-prl-marco-normativo-agentes-biologicos.mjs
 */
const URL_BASE = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!URL_BASE || !SERVICE_KEY) {
  console.error("❌ Faltan NEXT_PUBLIC_SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const HEADERS = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json" };
