const S1 = "marco-desarrollo-normativo-prl";
console.log(`📝 flashcards (${S1})...`);
await insertar("flashcards", [
  { anverso: "¿Qué es la Ley 31/1995, de Prevención de Riesgos Laborales, como norma de cabecera del sistema español de PRL?", reverso: "La ley que establece el marco general de derechos y obligaciones en materia de seguridad y salud en el trabajo, aplicable a cualquier actividad, y que sirve de base a partir de la cual se desarrollan los reglamentos específicos posteriores" },
  { anverso: "¿Qué es un reglamento de desarrollo de la Ley 31/1995 (por ejemplo, el RD 1627/1997 o el RD 664/1997)?", reverso: "Una norma reglamentaria (Real Decreto) que desarrolla en detalle un aspecto concreto ya previsto de forma general en la Ley 31/1995 (obras de construcción, agentes biológicos, equipos de trabajo), fijando disposiciones mínimas específicas para ese ámbito" },
  { anverso: "¿Qué es la evaluación de riesgos laborales, como obligación empresarial derivada de la Ley 31/1995?", reverso: "El proceso mediante el cual se identifican los peligros presentes en el trabajo y se valora la magnitud de los riesgos que suponen, sirviendo de base para planificar las medidas preventivas necesarias en cada puesto de trabajo" },
  { anverso: "¿Qué es la planificación de la actividad preventiva, como consecuencia directa de la evaluación de riesgos?", reverso: "El conjunto de medidas concretas (técnicas, organizativas, de formación) que se establecen a partir de los resultados de la evaluación de riesgos, con el fin de eliminar o reducir los riesgos detectados a un nivel aceptable" },
  { anverso: "¿Qué es el deber de protección del empresario, como principio central de la Ley 31/1995?", reverso: "La obligación legal del empresario de garantizar la seguridad y la salud de los trabajadores a su servicio en todos los aspectos relacionados con el trabajo, adoptando las medidas necesarias para ello dentro del marco de sus responsabilidades" },
  { anverso: "¿Qué son los servicios de prevención, como recurso organizativo previsto por la normativa de PRL?", reverso: "Las estructuras (propias de la empresa, mancomunadas o ajenas contratadas) encargadas de asesorar y asistir al empresario, a los trabajadores y a sus representantes en materia de prevención de riesgos, incluida la evaluación de riesgos y la planificación de medidas preventivas" },
  { anverso: "¿Qué es la formación e información de los trabajadores, como derecho reconocido por la Ley 31/1995?", reverso: "El derecho de todo trabajador a recibir información sobre los riesgos de su puesto de trabajo y una formación teórica y práctica suficiente y adecuada en materia preventiva, tanto en el momento de su contratación como cuando cambien sus funciones o se introduzcan nuevos equipos o tecnologías" },
  { anverso: "¿Qué es el derecho de paralización de la actividad, reconocido a los trabajadores por la Ley 31/1995 en situaciones de riesgo grave e inminente?", reverso: "La facultad del trabajador de interrumpir su actividad y, si es necesario, abandonar el lugar de trabajo cuando considere que existe un riesgo grave e inminente para su vida o su salud, sin que ello pueda suponerle perjuicio alguno" },
  { anverso: "¿Por qué la normativa de PRL combina disposiciones de carácter general (Ley 31/1995) con normas específicas de cada sector o actividad (construcción, agentes biológicos, equipos de trabajo)?", reverso: "Porque cada actividad presenta riesgos característicos distintos que requieren medidas concretas y adaptadas, y una única norma general no podría detallar con precisión suficiente las exigencias particulares de cada tipo de trabajo o exposición" },
  { anverso: "¿Por qué es relevante que el oficial de cementerio comprenda el marco general de la PRL, más allá de las medidas concretas de seguridad de cada tarea específica?", reverso: "Porque comprender los principios generales (evaluación de riesgos, jerarquía de medidas, derechos y obligaciones) permite interpretar con criterio cualquier situación de riesgo no prevista explícitamente en un procedimiento concreto, adaptándose a circunstancias nuevas con una base sólida" },
].map((f) => ({ ...f, tema_slug: TEMA, seccion: S1 })));

